import {world,STATES,PRESETS,FEATURES,needs,perceive,decide,tick,addNode,clamp} from './engine.mjs';
const $=id=>document.getElementById(id),pct=v=>`${Math.round(v*100)}%`,fmt=v=>Number(v).toFixed(3);
let w=world(),selected='npc-0',target='npc-1',inspected=null,experiment=null,runActor=null,busy=false;
const actor=()=>w.npcs.find(n=>n.id===selected),other=()=>w.npcs.find(n=>n.id===target);
function options(el,items){el.replaceChildren(...items.map(([v,label])=>{const o=document.createElement('option');o.value=v;o.textContent=label;return o;}));}
function slider(label,value,min,max,step,onchange,format=pct){const wrap=document.createElement('label');wrap.className='slider';const text=document.createElement('span');text.textContent=label;const out=document.createElement('output');out.textContent=format(value);const input=document.createElement('input');Object.assign(input,{type:'range',min,max,step,value});input.setAttribute('aria-label',label);input.oninput=()=>{out.textContent=format(+input.value);onchange(+input.value);};wrap.append(text,out,input);return wrap;}
options($('preset'),Object.keys(PRESETS).map(p=>[p,p]));options($('state'),Object.keys(STATES).map(p=>[p,p]));
function controls(){const n=actor();$('preset').value=w.preset;$('state').value=n.state;
 $('env').replaceChildren(...Object.entries(w.env).map(([k,v])=>slider(k==='qi'?'Available qi':'Ambient danger',v,0,1,.01,x=>{w.env[k]=x;update();})));
 $('actor').replaceChildren(slider('Health',n.hp,0,1,.01,x=>{n.hp=x;update();}),slider('Energy',n.energy,0,1,.01,x=>{n.energy=x;update();}),slider('Food units',n.food,0,8,1,x=>{n.food=x;update();},v=>String(v)),slider('Position',n.x,-15,15,1,x=>{n.x=x;update();},v=>String(v)));
 $('traits').replaceChildren(...Object.entries(n.traits).map(([k,v])=>slider(k,v,0,1,.01,x=>{n.traits[k]=x;update();})));
 options($('target'),w.npcs.filter(t=>t.id!==n.id).map(t=>[t.id,t.name]));$('target').value=target;ties();update();
}
function ties(){const n=actor(),t=other();const hostile=document.createElement('label');hostile.className='check';const cb=document.createElement('input');cb.type='checkbox';cb.checked=t.hostile;cb.onchange=()=>{t.hostile=cb.checked;update();};hostile.append(cb,document.createTextNode('Target shows hostile intent'));
 $('ties').replaceChildren(slider('Trust toward target',n.relations[t.id]||0,-100,100,1,x=>{n.relations[t.id]=x;update();},v=>String(Math.round(v))),slider('Grudge toward target',n.grudges[t.id]||0,0,100,1,x=>{n.grudges[t.id]=x;update();},v=>String(Math.round(v))),slider('Target health',t.hp,0,1,.01,x=>{t.hp=x;update();}),slider('Target position',t.x,-15,15,1,x=>{t.x=x;update();},v=>String(v)),hostile);
}
function update(){const n=actor(),d=decide(w,n),p=d.perception,mapLo=Math.min(-15,...w.npcs.map(t=>t.x))-1,mapHi=Math.max(15,...w.npcs.map(t=>t.x))+1;$('name').textContent=n.name;$('life').textContent=`${n.state} · ${n.genome.nodes.length} hidden features · Gen ${n.genome.generation}`;$('tick').textContent=`TICK ${String(w.tick).padStart(3,'0')}`;
 $('cast').replaceChildren(...w.npcs.map(t=>{const b=document.createElement('button');b.className=`cast-row ${t.id===selected?'selected':''}`;b.innerHTML=`<span class="portrait">${['林','沈','白','灵'][w.npcs.indexOf(t)]}</span><span><strong>${t.name}</strong><small>${t.state} · HP ${pct(t.hp)}</small></span><i>${t.hostile?'⚑':'↗'}</i>`;b.onclick=()=>{selected=t.id;if(target===selected)target=w.npcs.find(v=>v.id!==selected).id;inspected=null;controls();};return b;}));
 $('map').innerHTML=`<div class="map-line"></div>${w.npcs.map((t,i)=>`<div class="map-dot ${t.id===n.id?'focus':''} ${t.hostile?'hostile':''}" style="left:${7+(t.x-mapLo)/(mapHi-mapLo)*86}%;top:${i%2?57:12}px"><span>${['林','沈','白','灵'][i]}</span><small>${t.name.split(' ')[0]} · ${t.x}</small></div>`).join('')}<span class="map-caption">ONE-DIMENSIONAL TEST WORLD / AUTO-SCALED POSITIONS</span>`;
 $('needs').innerHTML=Object.entries(p.needs).map(([k,v])=>`<div><span>${k}</span><b>${pct(v)}</b><div class="bar"><i style="width:${v*100}%"></i></div></div>`).join('');
 $('perception').innerHTML=p.targets.length?p.targets.map(t=>`<div><strong>${t.name}</strong><span>distance ${t.distance.toFixed(1)} · strength ${t.relativePower.toFixed(1)}× · ${t.hostile?'hostile':'no hostile signal'} · injury ${pct(t.injury)}</span></div>`).join(''):'<p>No living targets within sensing range.</p>'; perception.insertAdjacentHTML('beforeend','<div><strong>Personal danger exposure</strong><span>'+pct(p.danger)+'</span></div>');
 $('intent').textContent=d.choice?.action||'No action';$('intent-target').textContent=d.choice?`→ ${d.choice.label} · ${pct(d.choice.share)} preference share`:'Actor is dead. Reset health to resume.';$('goal').innerHTML=n.goal?`<span class="badge">${n.goal.key.split(':')[0]} commitment · ${n.goal.remaining} tick${n.goal.remaining===1?'':'s'} left</span>`:'<span class="hint">No active commitment yet.</span>';
 $('pair-count').textContent=`${d.options.filter(c=>c.valid).length} / ${d.options.length} AVAILABLE`;
 if(!inspected||!d.options.some(c=>c.key===inspected))inspected=d.choice?.key||d.options[0]?.key;
 $('pairs').replaceChildren(...d.options.map(c=>{const row=document.createElement('tr');row.className=`${c.key===d.choice?.key?'winner':''} ${c.valid?'':'blocked'} ${c.key===inspected?'inspected':''}`;row.tabIndex=0;row.setAttribute('aria-label',`Inspect ${c.action} toward ${c.label}`);row.innerHTML=`<td><strong>${c.action}</strong><small>${c.label}</small></td><td>${fmt(c.score)}</td><td>${c.valid?pct(c.share):'—'}</td><td><span class="badge ${c.valid?'ok':'no'}">${c.valid?'Available':'Blocked'}</span></td>`;const choose=()=>{inspected=c.key;update();};row.onclick=choose;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};return row;}));
 const c=d.options.find(c=>c.key===inspected);if(c){$('inspect-name').textContent=`${c.action} → ${c.label}`;$('pair-features').innerHTML=`<p class="gate ${c.valid?'':'closed'}">${c.reason}</p><div class="feature-grid">${['need','benefit','risk','affinity','resentment','commitment','switchCost'].map(k=>`<span>${k}<b>${c.features[k].toFixed(2)}</b></span>`).join('')}</div>`;$('trace').innerHTML=[...c.terms].sort((a,b)=>Math.abs(b.value)-Math.abs(a.value)).map(t=>`<div class="trace"><span>${t.id.replace('seed:','F / ').replace('branch:','B / ').replace('input:','Direct / ')}<small>${t.weight.toFixed(2)} × ${t.activation.toFixed(2)}</small></span><b class="${t.value<0?'negative':''}">${t.value>=0?'+':''}${fmt(t.value)}</b></div>`).join('')+`<div class="trace"><span>Bias → score</span><b>${fmt(c.bias)} → ${fmt(c.score)}</b></div>`;}
 $('memories').replaceChildren(...n.memory.slice(0,6).map(m=>{const p=document.createElement('p');p.textContent=`Tick ${m.tick} · ${m.kind}${m.actor?' by '+w.npcs.find(t=>t.id===m.actor)?.name:''}${m.target?' → '+w.npcs.find(t=>t.id===m.target)?.name:''}`;return p;}));
 $('journal').innerHTML=w.journal.length?w.journal.map(e=>`<div class="event"><span>${String(e.tick).padStart(3,'0')}</span><p><strong>${e.name}</strong> · <b>${e.action}</b> → ${e.target}<small>${e.result.text}</small></p></div>`).join(''):'<p class="hint">Resolve a tick to see actions, actual benefits, costs, and reactions.</p>';
}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el===b));document.querySelectorAll('.tab-page').forEach(el=>el.hidden=el.id!==b.dataset.tab);});
$('preset').onchange=e=>{w=world(e.target.value);inspected=null;controls();};$('state').onchange=e=>{actor().state=e.target.value;inspected=null;controls();};$('target').onchange=e=>{target=e.target.value;ties();};$('reset').onclick=()=>{w=world($('preset').value);inspected=null;controls();};$('step').onclick=()=>{tick(w);controls();};$('ten').onclick=()=>{for(let i=0;i<10;i++)tick(w);controls();};
$('mutation').oninput=e=>$('mutation-out').textContent=pct(+e.target.value);
const worker=new Worker('./worker.js',{type:'module'});
function setBusy(value){busy=value;$('evolve').disabled=value;$('stress').disabled=value;$('apply').disabled=value;}
worker.onmessage=({data})=>{if(data.kind==='progress'){$('progress').textContent=`Completed generation ${data.row.generation}.`;return;}setBusy(false);if(data.kind==='error'){$('progress').textContent=`Experiment stopped: ${data.message}`;return;}if(data.kind==='audit'){const a=data.result;$('audit').innerHTML=`<div class="result-stats"><div><b>${a.passed?'PASS':'CHECK'}</b><span>Structural invariants</span></div><div><b>${a.cases.toLocaleString()}</b><span>Decision contexts</span></div><div><b>${a.gateFailures}</b><span>Gate violations</span></div></div><p>100 generations · maximum |weight| ${a.maxWeight.toFixed(2)} / 3 · ${a.finiteFailures} non-finite policies</p><p class="hint">${a.flips} changes of preferred action–target pair across generations. ${pct(a.saturation)} of selected hidden activations exceeded |0.98|. These are diagnostics, not pass/fail measures of wisdom. Seed ${a.seed}; mutation probability 100%.</p>`;$('progress').textContent='Stress audit completed.';return;}
 experiment=data.result;drawEvolution(experiment);$('progress').textContent=`Completed ${experiment.generations} generations × ${experiment.population} policies × 5 scenarios × 12 ticks.`;$('apply').hidden=false;$('apply-note').textContent=`Champion can be applied to ${runActor.name}. Applying changes the policy only; the experiment preserves the selected NPC’s traits and memories.`;};
worker.onerror=e=>{setBusy(false);$('progress').textContent=`Worker could not run: ${e.message}`;};
$('evolve').onclick=()=>{if(busy)return;setBusy(true);runActor={id:actor().id,name:actor().name};$('apply').hidden=true;$('progress').textContent='Evaluating generations in five reset worlds…';worker.postMessage({kind:'evolve',args:{base:actor().genome,traits:actor().traits,seed:Number($('seed').value)>>>0,generations:+$('generations').value,population:+$('population').value,rate:+$('mutation').value,objective:$('objective').value}});};
$('stress').onclick=()=>{if(busy)return;setBusy(true);$('progress').textContent='Auditing 100 unselected generations across every life state…';worker.postMessage({kind:'audit',seed:Number($('seed').value)>>>0});};
$('add-node').onclick=()=>{const ok=addNode(actor().genome,Number($('seed').value)>>>0);$('node-status').textContent=ok?'Added a homologous node; current policy scores are preserved.':'This seeded branch already exists, or the 10-node cap was reached. Try another seed.';update();};
$('apply').onclick=()=>{if(!experiment)return;const n=w.npcs.find(n=>n.id===runActor.id);n.genome=structuredClone(experiment.champion);$('apply-note').textContent=`Champion applied to ${n.name}. Physical checks still use ${n.state}; training used a Cultivator. Test the transfer in Decision lab.`;controls();};
function drawEvolution(e){const all=e.history.flatMap(h=>[h.best,h.mean]).concat(e.baseline.fitness),lo=Math.min(...all)-.05,hi=Math.max(...all)+.05;const x=i=>50+i*620/Math.max(1,e.history.length-1),y=v=>210-(v-lo)/(hi-lo)*170;const path=key=>e.history.map((h,i)=>`${i?'L':'M'}${x(i)},${y(h[key])}`).join(' ');$('chart').innerHTML=`<svg viewBox="0 0 720 260" role="img" aria-label="Best and mean realized fitness by generation"><line x1="50" y1="210" x2="680" y2="210" stroke="#344541"/><line x1="50" y1="${y(e.baseline.fitness)}" x2="680" y2="${y(e.baseline.fitness)}" stroke="#82775d" stroke-dasharray="4 5"/><path d="${path('mean')}" fill="none" stroke="#708a99" stroke-width="2"/><path d="${path('best')}" fill="none" stroke="#9ed2ad" stroke-width="3"/><text x="5" y="45" fill="#9ca8a2" font-size="10">${hi.toFixed(2)}</text><text x="5" y="210" fill="#9ca8a2" font-size="10">${lo.toFixed(2)}</text><text x="50" y="240" fill="#9ca8a2" font-size="11">GEN 1</text><text x="620" y="240" fill="#9ca8a2" font-size="11">GEN ${e.generations}</text></svg><div class="chart-legend"><span>● Best</span><span>● Population mean</span><span>┄ Original policy</span></div>`;
 $('evo-summary').innerHTML=`<div class="result-stats"><div><b>${fmt(e.baseline.fitness)}</b><span>Original fitness</span></div><div><b>${fmt(e.best.fitness)}</b><span>Champion fitness</span></div><div><b>${e.champion.nodes.length}</b><span>Hidden features</span></div></div><p class="hint">Seed ${e.seed} · ${e.objective} objective · exact same scenarios for training and reporting; no held-out generalization claim.</p>`;
 $('episode-results').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Champion episode</th><th>HP</th><th>Growth</th><th>Healing given</th><th>Unprovoked damage</th></tr></thead><tbody>${e.best.detail.map(d=>`<tr><td>${d.preset}</td><td>${pct(d.hp)}</td><td>${fmt(d.progress)}</td><td>${fmt(d.helped)}</td><td>${fmt(d.unprovoked)}</td></tr>`).join('')}</tbody></table></div>`;
}
$('export').onclick=()=>{const data={schemaVersion:2,world:w,selected,target,experiment};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='xianxia-architecture-v2.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('architecture-content').innerHTML=[
 ['01 / Perception','The mind sees nearby living targets: distance, injury, provisions, visible hostility, relative power, trust, and grudges. It has no target identity embedding to memorize a particular NPC. Sensing is exact in this experiment; uncertainty is future work.'],
 ['02 / Needs & memory','Health deficit, energy deficit, hunger, and ambition form needs. Directed trust and grudges summarize social events. A short commitment supplies a preference bonus and switching cost, not a hard lock. The event log is visible memory; only trust, grudges, and commitment feed the policy.'],
 ['03 / Evolving policy','Every action–target pair receives the same feature schema and shared scoring network. Hidden features are anonymous: their names identify ancestry, not empathy or morality. Weights and biases stay in [−3, 3]. Crossover aligns matching ancestry IDs and retains the first parent’s unmatched nodes. New nodes initially duplicate a feature and split its output weight, preserving every score.'],
 ['04 / Feasible action–target pairs','The world requires living actors, physical bodies where appropriate, interaction range, provisions, energy, actual target injury for aid, and qi plus cultivation access for practice. It does not require an attack to be wise, justified, or likely to win. There is always Rest or Observe for a living actor.'],
 ['05 / Execution & consequences','Actors execute in a rotating sequential order, using the current world. Execution validates again. Aid spends food and energy and heals a target. Trade shares provisions at a cost. Attacks damage both sides through deterministic retaliation. Cultivation consumes energy. Rest consumes food for embodied healing; spirits regenerate without food. Retreat changes position. Social events change the recipient’s memories. Ambient danger causes small exposure damage.'],
 ['Selection & inheritance','The generations test evolves neural policy only. Traits remain fixed, bodies reset as Cultivators, and memories reset every episode. Elite selection uses actual health, cultivation progress, aid, resource use, and unprovoked damage over 12 ticks. It is a small deterministic genetic experiment, with no full NEAT speciation or ecological reproduction. Life state and relationships are never inherited by the policy test.'],
 ['Known simplifications','The world is a one-dimensional line. Retreat moves away from hostiles and halves personal exposure; ambient danger is filtered through that exposure. There is no approach action, pathfinding, hunger damage, inventory variety, learning during life, probabilistic perception, or realm progression. Physical consistency can be tested; coherent values and generalization require broader scenarios and longer rollouts.'],
 ['What to challenge','Set a rival outside range; attacks must be blocked. Set food to zero; aid and trade must be blocked. Turn a mortal into a spirit; physical actions must disappear. Increase rival strength; the attack risk feature should rise, though an aggressive policy can still choose it. Add a neutral node; all scores should stay equal. Evolve, apply the champion, then challenge it in other life states.']
 ].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('');
controls();

